window.DOSIK=window.DOSIK||{};DOSIK["yc_academic"]={"1":[{"t":"tree","title":"학업문제의 원인","root":"학업문제","branches":[["학습 능력의 문제","특정 영역에서의 낮은 학습 능력의 문제와 · 낮은 지능의 문제로 구분할 수 있다"],["학습 태도의 문제","공부에 대한 반감, 공부 습관 미형성 등이 될 수 있다"],["개인 내 요인","성격, 적성과 흥미의 불일치, 역기능적 사고 등과 관련이 있다"],["가정 내 요인","부모, 형제, 가족 내 정서와 관련이 있다"]]}],"2":[{"t":"tree","title":"학습의 인지적 요인","root":"학습의 인지적 요인","branches":[["지능검사","학습자의 학습 취약점들을 보강하는 계획을 세우는데 유용하다"],["학업성적 하락","점차적으로 하락하는 경우 선행학습의 결손이 누적되었을 수도 있다"],["기초학업능력","파악하기 위해서는 표준화된 학업성취검사를 활용하는 것이 좋다"],["선행 학습 수준","상담자가 파악하기 어려운 경우, 교사와 부모의 협조를 얻어서 간접적으로 파악할 수 있다"]]}],"3":[{"t":"tree","title":"학습의 환경적 요인","root":"학습의 환경적 요인","branches":[["사회경제적 지위","가정의 사회경제적 지위는 부모의 교육적 관심을 매개로 하여 자녀의 학업에 영향을 끼칠 수 있다"],["교사의 기대","학생에 대한 교사의 자기충족적 예언은 학생의 학습노력과 성취 수준에 영향을 줄 수 있다"],["학생의 반응도","교사의 긍정적 기대에 대한 학생의 반응도는 다시 교사의 기대에 영향을 줄 수 있다"],["또래집단","학습태도가 유사한 것으로 지각된 또래집단에서는 학습에 긍정적 또는 부정적 영향을 끼칠 가능성이 커진다"]]},{"t":"tree","title":"수면과 학습","root":"수면과 학습","branches":[["긴장감과 스트레스","높은 긴장감과 스트레스로 밤잠을 이루기 힘든 경우에는 30분 정도 가벼운 운동 후 따뜻한 물로 샤워를 한다"],["암기과목","잠자기 전에 암기과목을 공부하는 것이 효율적이다"],["렘(REM)수면","단기기억이 장기기억으로 저장되는 과정은 렘(REM)수면 중에 대부분 이루어진다"],["낮잠","두뇌피로를 풀고, 학습효과를 상승시키는데 효과가 있으므로 30분 정도 자는 것이 좋다"]]}],"5":[{"t":"tree","title":"목표설정과 동기","root":"목표설정","branches":[["목표헌신","학습목표 설정에 대한 학습자의 헌신(commitment)에 영향을 주는 요인은 개인적 요인과 사회적 요인이 있다"],["목표의 형태","목표설정이 행동변화로 연결되기 위해서는 목표의 형태가 적절해야 한다 · 막연하고 모호한 형태가 아니라 명확한 형태의 목표가 동기향상에 기여한다"],["자기효능감","목표헌신에 영향을 주는 요인이다 · 학업적 자기효능감이 높아지면 학습동기 향상에 도움이 된다"]]},{"t":"tree","title":"학습동기이론","root":"학습동기","branches":[["행동주의적 관점","학습동기는 강화와 소거에 의해 조절될 수 있다"],["매슬로우(A. Maslow)","소속과 애정의 욕구는 결핍욕구에 해당된다"],["귀인이론","인간의 동기가 결과의 원인을 무엇으로 지각하느냐에 따라서 달라진다고 본다"],["자기결정성","자신이 선택한 행동에 대해서 동기가 높아지고, 선택하지 않은 행동에 대해서는 동기가 낮아진다는 개념이다"],["기대가치이론","현재 행동이 가져 올 미래의 결과를 평가하는 기준을 기대와 가치로 본다"],["친구의 칭찬 장면","다른 친구가 성공적으로 읽기 수행을 하고나서 칭찬받는 장면을 본 후, 자신도 그와 같이 하면 칭찬을 받을 것이라고 기대하고 동기화된다"]]},{"t":"def","term":"동기","text":"내재적 동기와 외재적 동기로 구분할 수 있다"}],"6":[{"t":"def","term":"초인지 전략","text":"주 전략인 인지전략을 보조한다는 측면에서 보조 전략으로 불리기도 한다"},{"t":"table","title":"학습전략","head":["전략","내용"],"rows":[["계획하기","목표설정, 개관, 과제분석 등을 통해 전략 사용을 계획하고 사전지식을 활용하는 것이다"],["점검하기","스스로 만든 질문을 통해 평가하기, 문제 푸는 속도를 점검하는 것 등과 같은 방법이 있다"],["조절하기","과제를 수행할 때 자신의 행동을 점검하면서 더 적절한 것으로 바꿔 나가는 것이다"],["조직화","학습 내용들 간의 논리적 관계를 염두에 두고 내용을 정리하는 것이다"]]}],"7":[{"t":"flow","title":"정보처리","steps":["감각등록기에서 받아들인 정보는 주의를 기울이지 않으면 그대로 사라진다","작업기억은 정보가 장기기억으로 이동되거나 장기기억 내 지식과 통합될 수 있도록 전달자 기능을 한다","장기기억으로 들어가기 위해서는 정보의 심층적인 내용을 이해하고 있어야 한다"]},{"t":"tree","title":"작업기억","root":"작업기억","branches":[["저장 용량","한계가 있기 때문에 많은 정보를 묶어서 기억하거나 처리하는 방법이 제안된다"],["처리 수준","7±2 단위 정도의 정보를 한 번에 처리할 수 있는 수준이다"],["청킹","작업기억에서 한 번에 많은 정보를 처리하기 위한 방법으로 청킹(chunking) 등이 있다"]]},{"t":"vs","title":"의미기억과 일화기억","cols":[{"name":"의미기억","items":["일반지식에 관한 기억"]},{"name":"일화기억","items":["개인적 경험과 관계된 기억"]}]},{"t":"table","title":"장기기억의 용어","head":["용어","내용"],"rows":[["부호화","영향을 미치는 중요한 요인은 정교화와 조직화이다"],["명제","장기기억 속 지식과 의미의 기본단위이다"]]}],"8":[{"t":"def","term":"조직화 전략","text":"학습 내용들 간 논리적 관계를 염두에 두고 내용을 정리하는 것이다"},{"t":"table","title":"읽기전략","head":["전략","방법"],"rows":[["질문하기","굵은 글씨체의 표제를 질문으로 변형한다"],["훑어보기(Survey)","요약된 단락을 읽는다"],["읽기(Reading)","읽는 동안 중요한 개념 혹은 질문에 대한 답이 되는 부분에 표시를 한다"],["복습하기(Review)","전반적으로 다시 읽으며 주요 핵심개념을 이해했는가 확인한다"],["암송하기(Recite)","중요한 부분을 속으로 혹은 소리내어 암송한다"]]}],"9":[{"t":"tree","title":"시간관리전략","root":"시간관리","branches":[["중요성","시간계획과 시간관리는 능동적 학습에서 중요하다"],["목적","시간계획과 시간관리의 목적은 학습이 효과적으로 이루어지도록 하기 위한 것이다"],["지연","계획대로 하지 못하고 시간을 허비하는 이유 중에 지연(procrastination)이 있다"],["시간배분과 시간조절","시간을 효율적으로 사용하기 위한 시간배분과 시간조절은 학업성취와 연결된다"],["우선순위","제한된 시간 내에 원하는 일을 해내는데 있어, 우선순위 정하기는 결정적인 역할을 한다"]]}],"10":[{"t":"tree","title":"자기통제력 향상","root":"주의집중력 향상전략","branches":[["내재적 언어","과제 완수 단계마다의 사고를 나누어서 각 단계별로 필요한 언어를 내재화하는 과정이 필요하다 · 과제의 성격에 맞추어 효율적으로 집중력을 향상시킬 수 있다"],["ADHD","내재적 언어를 통한 자기통제력 향상은 특히 주의력결핍 과잉행동장애(ADHD) 학생의 자기통제력 향상을 위한 방법으로 제안된다"],["칭찬","계획대로 효율적인 방법으로 학습한 자신을 칭찬하는 과정을 통해 성취감과 자신감을 갖도록 할 수 있다"],["Think Aloud 훈련","주의집중력 향상을 위한 개입전략으로 활용할 수 있다"]]},{"t":"tree","title":"주의집중력 문제의 원인","root":"주의집중력 문제","branches":[["생물학적 원인","생물학적 원인에 의한 주의집중력 문제를 가진 내담자는 어릴 때부터 많은 호기심, 높은 에너지 수준을 가지고 있음을 알아야 한다"],["학습 결손","학습 결손의 누적은 주의집중력에 영향을 미친다"],["생활환경","지나치게 비구조화 되어 있는 생활환경은 주의집중력 문제의 원인이 되기도 한다"]]}],"11":[{"t":"def","term":"학습부진","text":"학업성취수준이 잠재적인 능력에 미치지 못하고 현격하게 뒤떨어지는 상태를 가리킨다 · 정상적인 지적 능력을 가지고 있으나, 심리환경적 요인에 의해 학업이 떨어지는 것을 의미한다"},{"t":"tree","title":"학습부진의 양상","root":"학습부진","branches":[["기간","일시적인 기간에 나타나기도 하고, 장기간에 걸쳐 나타나기도 한다"],["시험성적","시험성적에서 학령수준에 못 미치는 수행이 나타날 수 있다"],["사회정서","사회정서적으로 적응하는데 어려움이 있을 수 있다"],["자기효능감","학습의 실패경험으로 낮은 자기효능감의 문제가 나타날 수 있다"]]},{"t":"tree","title":"학습부진의 원인","root":"학습부진","branches":[["외적환경","교사와의 관계, 친구와의 관계로 인한 학습부진은 외적환경의 영향이 원인이다"],["물리적 환경","물리적 환경, 심리적 환경이 원인이 되기도 한다"]]},{"t":"table","title":"학습부진의 유형","head":["유형","내용"],"rows":[["교과학습부진","해당 학년 교과 교육과정에 제시된 최소 수준의 목표에 도달하지 못한 경우"],["학습장애(learning disabilities)","중재반응모형이나 개인내적 처리과정 결함 접근으로도 판별한다"],["영재아 학습부진","빠른 지적 성장에 비해 신체적, 정서적, 사회적 성장이 늦을 수 있다"]]}],"12":[{"t":"tree","title":"특정학습장애","root":"특정학습장애","branches":[["명칭","DSM-5에서는 특정학습장애라고 명명한다"],["지능","특정학습장애 아동은 정상수준의 지능을 가지고 있다 · 지능이 현저하게 낮지 않으나 학습하고 학업기술을 사용하는데 어려움을 보인다"],["성취","특정 학습 영역을 위한 중재를 받았음에도 불구하고 읽기, 쓰기, 수학 영역 중 적어도 한 가지 영역에서 어려움을 보인다 · 기대수준보다 낮은 성취를 보인다"],["지속","학습장애가 성인기에도 지속될 수 있다"],["산술 곤란형","특정학습장애에 해당한다"]]},{"t":"tree","title":"학습장애의 분류","root":"학습장애","branches":[["학업적 학습장애","읽기장애 · 수학장애"],["발달적 학습장애","주의집중 장애, 사고장애"]]}],"13":[{"t":"table","title":"ADHD의 증상","head":["증상","내용"],"rows":[["부주의","지시를 완수하지 못하고, 학업, 잡일, 작업장에서의 임무 완성에 어려움을 겪는다 · 학습과제, 연필, 책 등 과제와 활동에 필요한 물건들을 자주 잃어버리거나 일상적인 활동을 잊어버린다"],["과잉행동-충동성","차례를 기다리지 못하거나 종종 다른 사람의 활동을 방해하고 간섭한다 · 손발을 가만히 두지 못하거나 부적절한 상황에서 지나치게 뛰어다니거나 기어오른다"]]},{"t":"tree","title":"강화 중재","root":"강화 중재","branches":[["강화활동","강화활동 계약의 사용, 규칙과 짝지어진 정적 강화, 문제행동 전환에 대한 강화활동을 포함한다"],["토큰 강화프로그램","학급중심의 토큰 강화프로그램에서는 하나 이상의 문제가 있는 학급상황이 중재의 목표가 된다"],["행동계약서","수행이 요구되는 교실 행동이 유용한 강화활동의 결과로서 명시된다"],["타임아웃","정적강화로부터의 타임아웃은 유용한 강화물의 박탈이 효과적이라는 점을 전제한다"]]}],"14":[{"t":"vs","title":"시험준비자","cols":[{"name":"능동형 준비자","items":["구체적이고 접근 가능한 과제를 선택한다"]},{"name":"수동적 준비자","items":["거의 계획을 세우지 않거나 막연한 계획을 세운다"]}]},{"t":"tree","title":"시험준비 전략","root":"시험준비","branches":[["노트정리","중요한 시험준비 학습기술이다"],["난이도와 경험","시험의 난이도와 경험에 따라 학습자에게 적합하고 효과적인 시험준비 전략이 필요하다"],["이해","단순히 기계적으로 암기하기보다 이해를 수반하는 학습이 효과적이다"]]},{"t":"tree","title":"시험불안 상담","root":"민주의 호소","branches":[["호소내용","민주의 호소내용은 시험불안에 관한 것임을 알아차리고 시험불안에 대해 다룬다"],["요인","시험불안의 요인인 걱정과 감정 중 어떤 요인이 현재 민주에게 더 큰 영향을 미치고 있는지를 파악한다"],["원인","민주가 경험하고 있는 시험불안의 원인을 탐색한다"],["상담관계","호소문제를 효과적으로 다루기 위해 민주와의 상담관계를 형성하는데 주력한다"]]}],"15":[{"t":"tree","title":"발표불안 개입","root":"발표불안","branches":[["사고 변화","내담자의 비합리적이고 왜곡된 사고를 합리적으로 변화시킨다"],["자기 대화하기","발표 전, 중, 후에 지속적으로 실시한다"],["칭찬과 격려","부모나 교사의 칭찬과 격려를 통해 자신감을 향상시킨다"],["체계적 둔감법","위계적 발표불안 리스트를 작성하여 불안이 가장 높은 단계부터 체계적 둔감법을 실시한다"]]}],"16":[{"t":"table","title":"학업 관련 심리검사","head":["검사","내용"],"rows":[["학업동기검사 AMT","학업적 자기효능감 척도와 학업적 실패내성 척도로 구성된다"],["HOME","캘드웰과 브래들리(B. Caldwell & R. Bradley, 1978)가 · 개발한 가정환경진단검사이다"],["K-WISC-Ⅴ","웩슬러 지능검사: 언어이해, 시공간, 유동추론, 작업기억, 처리속도의 다섯 가지 지표점수를 제공한다"],["BASA","기초학습기능 수행평가체제: 학생이 실제 학습하는 자료 자체를 평가도구로 사용함으로써 · 기초학습기능에 대한 수행 정도를 평가한다"],["학습전략검사 MLST","성격적 차원, 정서적 차원, 동기적 차원, 행동적 차원의 네 가지로 구성된다"],["학습성격유형검사 U&I","행동형, 규범형, 탐구형, 이상형의 네 가지 유형을 제시한다"]]}],"17":[{"t":"tree","title":"학업상담","root":"학업상담","branches":[["학습장애아 상담","장애의 발달양상에 대한 충분한 지식을 가지고 그들이 실현해 나가는 과정의 독특성을 이해해야 한다"],["조기진단","2차적 문제 발생의 예방을 위해 조기진단과 초기 개입이 필요하다"],["성취수준","내담자로 하여금 현재 성취수준을 수용하도록 촉진한다"],["결손 보완","기초학습능력의 결손이나 선수학습의 결손을 확인하고 이를 보완할 수 있는 대안탐색 과정을 도와야 한다"]]}]};
